scriptData.script:
const api = game.modules.get("artantares-mutations")?.api;
if (!api?.grant) return ui.notifications.warn(`${this.item.name}: Antares | Mutant's Handbook is not active, so nothing was added.`);
await api.grant(this, {
  "grants": [
    {
      "roll": "1d10",
      "text": "Limb",
      "res": [
        [
          1,
          4,
          [
            {
              "note": "Long arms: weapon Reach one step longer (set it on your weapons by hand)."
            },
            {
              "t": "dialog",
              "d": {
                "label": "Elongated Limbs (target): in-fighting against long arms +20",
                "trigger": "dialog",
                "script": "args.fields.modifier += 20;",
                "options": {
                  "targeter": true,
                  "hideScript": "return !(args.item?.system?.attackType == \"melee\");",
                  "activateScript": "return (args.item?.system?.attackType == \"melee\") && (args.actor?.statuses?.has(\"infighting\"));",
                  "submissionScript": ""
                }
              }
            }
          ],
          "Arms"
        ],
        [
          5,
          9,
          {
            "t": "mod",
            "k": "move",
            "v": 1
          },
          "Legs"
        ],
        [
          10,
          10,
          {
            "t": "dialog",
            "d": {
              "label": "Elongated Limbs: Critical hits to the Head +20 (Up in Arms Criticals)",
              "trigger": "takeDamage",
              "script": "if (args.loc == \"head\") args.critModifier = (Number(args.critModifier) || 0) + 20;",
              "options": {}
            }
          },
          "Neck"
        ]
      ]
    },
    {
      "roll": "1d10",
      "text": "Elastic",
      "res": [
        [
          1,
          8,
          null,
          "-"
        ],
        [
          9,
          10,
          {
            "note": "Elastic: retract to hide it, or extend 1-2 yards (about 3 yards reach)."
          },
          "Elastic"
        ]
      ]
    }
  ]
});
